#!/usr/bin/perl
use strict; use warnings;
use File::Path qw(make_path remove_tree);
use Cwd qw(abs_path);

my $APP = "/app";
my $WORK = "/tmp/opt";
my $PDS = 8;

# parse synonym families
my %fam; # lc word -> arrayref of synonyms (original case)
open(my $sf, "<", "$APP/synonyms.txt") or die $!;
while (my $line = <$sf>) {
    chomp $line;
    my @w = grep { length } map { s/^\s+|\s+$//gr } split(/,/, $line);
    for my $w (@w) { $fam{lc $w} = [@w]; }
}
close $sf;

# read input, split into paragraphs preserving separators
open(my $inf, "<", "$APP/input.tex") or die $!;
local $/; my $text = <$inf>; close $inf;

my @parts = split(/(\n[ \t]*\n)/, $text, -1); # even indices = paragraphs
my @pars;
for (my $i=0; $i<@parts; $i+=2) { push @pars, $parts[$i]; }

sub occurrences {
    my ($s) = @_;
    my @occ;
    while ($s =~ /([A-Za-z]+)/g) {
        my ($w,$st) = ($1, $-[0]);
        push @occ, { start=>$st, word=>$w, orig=>$w, fill=>[] } if exists $fam{lc $w};
    }
    return \@occ;
}

sub apply_words {
    my ($s, $occ, $idx) = @_; # idx: arrayref of chosen words per occurrence
    my @repl;
    for my $k (0..$#$occ) {
        my $w = $idx->[$k];
        next if lc $w eq lc $occ->[$k]{orig};
        my $orig = $occ->[$k]{orig};
        my $out;
        if ($orig =~ /^[A-Z][a-z]*$/) { $out = ucfirst(lc $w); }
        elsif ($orig =~ /^[A-Z]+$/) { $out = uc($w); }
        else { $out = lc $w; }
        push @repl, [$occ->[$k]{start}, length($occ->[$k]{orig}), $out];
    }
    for my $r (sort { $b->[0] <=> $a->[0] } @repl) {
        substr($s, $r->[0], $r->[1]) = $r->[2];
    }
    return $s;
}

sub score_log {
    my ($log) = @_;
    my ($cnt,$sum)=(0,0);
    while ($log =~ /Overfull \\hbox \(([0-9.]+)pt too wide\)/g) { $cnt++; $sum += $1; }
    return ($cnt,$sum);
}

# evaluate list of variant paragraphs in parallel. Returns arrayref of [cnt,sum]
sub evaluate {
    my ($variants, $tag) = @_;
    my $base = "$WORK/$tag";
    remove_tree($base); make_path($base);
    my $n = scalar @$variants;
    my @res = (undef) x $n;
    my $resfile = "$base/results.txt";
    open(my $rf, ">", $resfile) or die $!; close $rf;
    my $next = 0;
    my @pids;
    for my $w (1..$PDS) {
        my $pid = fork();
        die "fork: $!" unless defined $pid;
        if ($pid == 0) {
            # child
            my $i = $w-1;
            while ($i < $n) {
                my $dir = "$base/c$i";
                make_path($dir);
                symlink("$APP/main.tex", "$dir/main.tex");
                open(my $of, ">", "$dir/input.tex") or die $!;
                print $of $variants->[$i];
                close $of;
                my $log = `cd '$dir' && pdflatex -draftmode -interaction=nonstopmode main.tex 2>&1`;
                my ($c,$s) = score_log($log);
                open(my $af, ">>", $resfile) or die $!;
                print $af "$i $c $s\n";
                close $af;
                $i += $PDS;
            }
            exit 0;
        }
        push @pids, $pid;
    }
    waitpid($_,0) for @pids;
    open(my $in, "<", $resfile) or die $!;
    while (<$in>) { my ($i,$c,$s)=split; $res[0+$i]=[$c+0,$s+0]; }
    close $in;
    remove_tree($base);
    return \@res;
}

