my @text_pars;
my $sep = "\n\n";
for my $i (0..$#pars) {
    my $occ = occurrences($pars[$i]);
    push @text_pars, { text=>$pars[$i], occ=>$occ, idx=>[map { $_->{orig} } @$occ] };
}

# Determine paragraphs with overfull. Evaluate each paragraph alone.
my @variants = map { $_->{text} } @text_pars;
my $scores = evaluate(\@variants, "base");
for my $i (0..$#text_pars) {
    printf "par %2d occ=%2d score=%d/%0.2f\n", $i, scalar @{$text_pars[$i]{occ}}, @{$scores->[$i]};
}
print "----\n";

# optimize paragraphs with overfull
for my $p (0..$#text_pars) {
    next unless $scores->[$p][0] > 0;
    my $tp = $text_pars[$p];
    my $occ = $tp->{occ};
    my $best_cnt = $scores->[$p][0];
    my $best_sum = $scores->[$p][1];
    my $round = 0;
    while ($best_cnt > 0 && $round < 40) {
        $round++;
        my (@cand, @desc);
        for my $k (0..$#$occ) {
            my $orig = $occ->[$k]{orig};
            for my $syn (@{$fam{lc $orig}}) {
                next if lc $syn eq lc $tp->{idx}[$k];
                my @idx = @{$tp->{idx}};
                $idx[$k] = $syn;
                push @cand, apply_words($tp->{text}, $occ, \@idx);
                push @desc, "$k:$orig->$syn";
            }
        }
        my $sc = evaluate(\@cand, "p${p}r${round}");
        my ($bi, $bc, $bs) = (-1, $best_cnt, $best_sum);
        for my $j (0..$#cand) {
            my ($c,$s) = @{$sc->[$j]};
            if ($c < $bc || ($c == $bc && $s < $bs - 0.0001)) {
                ($bi,$bc,$bs) = ($j,$c,$s);
            }
        }
        if ($bi < 0) {
            print "par $p round $round STUCK at $best_cnt/$best_sum\n";
            last;
        }
        my ($k,$o,$nw) = split /:/, $desc[$bi];
        $tp->{idx}[$k] = $nw;
        $best_cnt = $bc; $best_sum = $bs;
        print "par $p round $round: $desc[$bi] -> $bc / $best_sum\n";
    }
    $tp->{newtext} = apply_words($tp->{text}, $occ, $tp->{idx});
    print "par $p final $best_cnt / $best_sum\n";
}

# write result
my $out = $text;
for my $i (0..$#parts) {
    next unless $i % 2 == 0;
    my $p = $i/2;
    $parts[$i] = $text_pars[$p]{newtext} if defined $text_pars[$p]{newtext};
}
my $new = join("", @parts);
open(my $of, ">", "$APP/input.tex.new") or die $!;
print $of $new; close $of;
print "wrote input.tex.new\n";

