  my ($variants,$tag)=@_;
  my $base="$WORK/$tag"; remove_tree($base); make_path($base);
  my $n=scalar @$variants; my $resfile="$base/results.txt";
  open(my $rf,">",$resfile) or die $!; close $rf;
  my @pids;
  for my $w (1..$PDS){
    my $pid=fork(); die "fork: $!" unless defined $pid;
    if($pid==0){
