  open(my $in,"<",$resfile) or die $!;
  while(<$in>){ my ($i,$c,$s)=split; $res[0+$i]=[$c+0,$s+0] if defined $i; }
  close $in; remove_tree($base);
  return \@res;
}

sub score_of { my $r=shift; return $r->[0]*1000 + $r->[1]; }

# baseline
